import { createRequire } from 'node:module'
import { mkdir } from 'node:fs/promises'
import { pathToFileURL } from 'node:url'

const require = createRequire(import.meta.url)
const { chromium } = require('C:\\Users\\Administrator\\AppData\\Local\\npm-cache\\_npx\\e41f203b7505f1fb\\node_modules\\playwright')
const origin = 'http://127.0.0.1:8099'
const outputDir = 'D:\\repository\\太仓G\\.task-state\\2334-visual-baseline'
const prototypePath = 'C:\\Users\\Administrator\\.dsh\\attachments\\v1\\files\\eb\\eb0fd730c6a416d76ceb5d7f61c858a5320b30099e52b7fc2efd47e99693560a\\index.html'

await mkdir(outputDir, { recursive: true })
const browser = await chromium.launch({ headless: true })
const context = await browser.newContext({ viewport: { width: 1440, height: 1100 }, deviceScaleFactor: 1 })
const page = await context.newPage()
await page.route('**/prod-api/**', (route) => route.abort())

for (const [name, route] of [['registration', '/register/add'], ['login', '/login']]) {
  await page.goto(`${origin}${route}`, { waitUntil: 'domcontentloaded', timeout: 30000 })
  await page.waitForTimeout(900)
  await page.screenshot({ path: `${outputDir}\\current-${name}.png`, fullPage: true })
}

await page.goto(pathToFileURL(prototypePath).href, { waitUntil: 'domcontentloaded', timeout: 30000 })
await page.waitForTimeout(900)
await page.screenshot({ path: `${outputDir}\\prototype-initial.png`, fullPage: true })
await browser.close()
console.log('Visual baseline screenshots saved under .task-state\\2334-visual-baseline')

